use std::path::Path;

use tauri::{AppHandle, Emitter, Manager, State};

use crate::db;
use crate::domain::{AgentTask, DiffStats, FileDiff, TaskStatus};
use crate::state::AppState;

fn now() -> String {
    chrono::Utc::now().to_rfc3339()
}

fn build_commit_message(task: &AgentTask, summary: Option<&str>) -> String {
    let subject = format!("{}: {}", task.jira_issue_key, task.title);
    match summary.map(str::trim).filter(|value| !value.is_empty()) {
        Some(summary) => format!(
            "{subject}\n\n{summary}\n\nGenerated by TicketBridge for {}.",
            task.jira_issue_key
        ),
        None => subject,
    }
}

pub fn start_commit(app: AppHandle, task_id: String) {
    std::thread::spawn(move || {
        if let Err(error) = commit_task(&app, &task_id, None) {
            fail_commit(&app, &task_id, &error);
        }
    });
}

fn commit_task(app: &AppHandle, task_id: &str, message: Option<String>) -> Result<String, String> {
    let state = app
        .try_state::<AppState>()
        .ok_or_else(|| "state unavailable".to_string())?;

    let (task, summary) = {
        let connection = state.db.lock().map_err(|error| error.to_string())?;
        let task = db::get_task(&connection, task_id)?
            .ok_or_else(|| format!("task not found: {task_id}"))?;
        let summary = match task.approved_plan_version.or(task.plan_version) {
            Some(version) => db::get_plan_version(&connection, task_id, version)?
                .map(|version| version.content.summary),
            None => None,
        };
        (task, summary)
    };

    match task.status {
        TaskStatus::Committing => {}
        TaskStatus::Failed => {
            let connection = state.db.lock().map_err(|error| error.to_string())?;
            db::update_task_status(&connection, task_id, TaskStatus::Committing, &now())?;
        }
        other => {
            return Err(format!(
                "task {task_id} cannot be committed from status {other:?}"
            ))
        }
    }

    let workspace_path = task
        .workspace_path
        .clone()
        .ok_or_else(|| "task has no workspace".to_string())?;
    let path = Path::new(&workspace_path);
    if !path.is_dir() {
        return Err(format!("workspace path does not exist: {workspace_path}"));
    }

    let commit_message = message
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| build_commit_message(&task, summary.as_deref()));

    // Phase 26: measure the change before it is committed (afterwards the
    // working tree diff is empty).
    if let Ok(stats) = crate::git::worktree_stats(path) {
        crate::metrics::record(
            app,
            "files.changed",
            stats.files_changed as f64,
            Some(task_id),
            serde_json::json!({ "additions": stats.additions, "deletions": stats.deletions }),
        );
    }

    let hash = crate::git::commit_all(path, &commit_message)?;

    {
        let connection = state.db.lock().map_err(|error| error.to_string())?;
        db::set_task_commit(&connection, task_id, &hash, &now())?;
        db::update_task_status(&connection, task_id, TaskStatus::PrCreating, &now())?;
    }
    crate::commands::cloud_socket::emit_task_updated(app, &state, task_id);
    let _ = app.emit(
        "commit://created",
        serde_json::json!({ "taskId": task_id, "commitHash": hash }),
    );
    crate::commands::github::start_publish(app.clone(), task_id.to_string());

    Ok(hash)
}

fn fail_commit(app: &AppHandle, task_id: &str, error: &str) {
    crate::logging::error(
        "commit",
        "commit failed",
        serde_json::json!({ "taskId": task_id, "error": error }),
    );
    if let Some(state) = app.try_state::<AppState>() {
        if let Ok(connection) = state.db.lock() {
            let _ = db::mark_task_failed(&connection, task_id, error, &now());
        }
        crate::commands::cloud_socket::emit_task_updated(app, &state, task_id);
    }
    let _ = app.emit(
        "commit://error",
        serde_json::json!({ "taskId": task_id, "error": error }),
    );
}

#[tauri::command]
pub fn commit_changes(
    app: AppHandle,
    task_id: String,
    message: Option<String>,
) -> Result<String, String> {
    commit_task(&app, &task_id, message)
}

#[tauri::command]
pub fn get_workspace_stats(state: State<AppState>, task_id: String) -> Result<DiffStats, String> {
    let workspace_path = {
        let connection = state.db.lock().map_err(|error| error.to_string())?;
        let task = db::get_task(&connection, &task_id)?
            .ok_or_else(|| format!("task not found: {task_id}"))?;
        task.workspace_path
            .ok_or_else(|| "task has no workspace yet".to_string())?
    };

    let path = Path::new(&workspace_path);
    if !path.is_dir() {
        return Err(format!("workspace path does not exist: {workspace_path}"));
    }

    crate::git::worktree_stats(path)
}

#[tauri::command]
pub fn get_workspace_diffs(
    state: State<AppState>,
    task_id: String,
) -> Result<Vec<FileDiff>, String> {
    let workspace_path = {
        let connection = state.db.lock().map_err(|error| error.to_string())?;
        let task = db::get_task(&connection, &task_id)?
            .ok_or_else(|| format!("task not found: {task_id}"))?;
        task.workspace_path
            .ok_or_else(|| "task has no workspace yet".to_string())?
    };

    let path = Path::new(&workspace_path);
    if !path.is_dir() {
        return Err(format!("workspace path does not exist: {workspace_path}"));
    }

    let stats = crate::git::worktree_stats(path)?;
    Ok(stats
        .files
        .iter()
        .map(|file| crate::git::file_diff(path, &file.path))
        .collect())
}

fn merge_task(app: &AppHandle, task_id: &str) -> Result<(), String> {
    let state = app
        .try_state::<AppState>()
        .ok_or_else(|| "state unavailable".to_string())?;

    let (task, repository, summary) = {
        let connection = state.db.lock().map_err(|error| error.to_string())?;
        let task = db::get_task(&connection, task_id)?
            .ok_or_else(|| format!("task not found: {task_id}"))?;
        let repository = db::get_repository(&connection, &task.repository_id)?
            .ok_or_else(|| format!("repository not found: {}", task.repository_id))?;
        let summary = match task.approved_plan_version.or(task.plan_version) {
            Some(version) => db::get_plan_version(&connection, task_id, version)?
                .map(|version| version.content.summary),
            None => None,
        };
        (task, repository, summary)
    };

    match task.status {
        TaskStatus::PrCreated | TaskStatus::Failed | TaskStatus::Interrupted => {}
        other => {
            return Err(format!(
                "task {task_id} cannot be merged from status {other:?}"
            ))
        }
    }

    let branch = task
        .branch_name
        .clone()
        .ok_or_else(|| "task has no branch".to_string())?;
    let base = repository.default_branch.clone();
    let repo_path = Path::new(&repository.local_path);

    if !repo_path.is_dir() {
        return Err(format!(
            "repository path does not exist: {}",
            repository.local_path
        ));
    }
    if !crate::git::is_git_repository(repo_path) {
        return Err(format!("{} is not a git repository", repository.local_path));
    }
    if !crate::git::branch_exists(repo_path, &branch) {
        return Err(format!("branch does not exist: {branch}"));
    }
    if !crate::git::rev_parse_verify(repo_path, &format!("refs/heads/{base}")) {
        return Err(format!("base branch does not exist: {base}"));
    }
    if !crate::git::is_clean(repo_path) {
        return Err(format!(
            "{} has uncommitted changes; commit or stash them before merging",
            repository.local_path
        ));
    }
    if crate::git::current_branch(repo_path).as_deref() != Some(base.as_str()) {
        crate::git::checkout_branch(repo_path, &base)?;
    }

    let message = build_commit_message(&task, summary.as_deref());
    crate::git::merge_branch(repo_path, &branch, &message)?;

    {
        let connection = state.db.lock().map_err(|error| error.to_string())?;
        db::update_task_status(&connection, task_id, TaskStatus::WaitingForReview, &now())?;
    }
    crate::commands::cloud_socket::emit_task_updated(app, &state, task_id);
    let _ = app.emit(
        "merge://completed",
        serde_json::json!({ "taskId": task_id, "branch": branch, "baseBranch": base }),
    );
    crate::logging::info(
        "merge",
        "merged task branch locally",
        serde_json::json!({ "taskId": task_id, "branch": branch, "baseBranch": base }),
    );

    if crate::commands::jira::is_connected(&state) {
        if let Err(error) = crate::commands::jira::sync_task(app, task_id) {
            let _ = app.emit(
                "jira://error",
                serde_json::json!({ "taskId": task_id, "error": error }),
            );
        }
    }

    Ok(())
}

/// Merges a task's branch into the repository's default branch locally, in
/// the working repository itself — instead of or in addition to publishing a
/// pull request for the branch.
#[tauri::command]
pub fn merge_locally(app: AppHandle, task_id: String) -> Result<(), String> {
    match merge_task(&app, &task_id) {
        Ok(()) => Ok(()),
        Err(error) => {
            crate::logging::error(
                "merge",
                "local merge failed",
                serde_json::json!({ "taskId": task_id, "error": error }),
            );
            Err(error)
        }
    }
}
